package secreview

import (
	"context"
	"os"
	"os/exec"
	"path/filepath"
	"testing"
	"time"
)

// Replicates internal/doctor/sandbox.go's execution pattern exactly.
func run(t *testing.T, dir string, body string, timeout time.Duration) {
	ctx, cancel := context.WithTimeout(context.Background(), timeout)
	defer cancel()
	hookPath := filepath.Join(dir, "hook-under-test")
	if err := os.WriteFile(hookPath, []byte(body), 0o755); err != nil {
		t.Fatal(err)
	}
	cmd := exec.CommandContext(ctx, hookPath)
	cmd.Dir = dir
	cmd.Env = []string{"PATH=" + os.Getenv("PATH"), "HOME=" + dir}
	start := time.Now()
	_ = cmd.Run()
	t.Logf("cmd.Run returned after %v", time.Since(start))
}

// Q3: does the timeout kill the process GROUP, or only the direct child?
func TestBackgroundedGrandchildSurvivesTimeout(t *testing.T) {
	dir := t.TempDir()
	beacon := filepath.Join(dir, "beacon")
	// Hook backgrounds a child that outlives the timeout and writes a beacon.
	body := "#!/bin/sh\n(sleep 4; : > " + beacon + ") &\nsleep 60\n"
	run(t, dir, body, 2*time.Second)
	// sandbox.go does `defer os.RemoveAll(dir)` here; t.TempDir cleans later.
	time.Sleep(4 * time.Second)
	if _, err := os.Stat(beacon); err == nil {
		t.Logf("FINDING: backgrounded grandchild SURVIVED the timeout and ran after the parent was killed")
	} else {
		t.Logf("grandchild did not survive: %v", err)
	}
}

// Does a double-forked daemon survive?
func TestDoubleForkSurvives(t *testing.T) {
	dir := t.TempDir()
	beacon := filepath.Join(dir, "beacon2")
	body := "#!/bin/sh\nnohup sh -c 'sleep 4; : > " + beacon + "' >/dev/null 2>&1 &\nexit 0\n"
	run(t, dir, body, 2*time.Second)
	time.Sleep(5 * time.Second)
	if _, err := os.Stat(beacon); err == nil {
		t.Logf("FINDING: nohup'd daemon SURVIVED")
	} else {
		t.Logf("daemon did not survive: %v", err)
	}
}

// Does cmd.Run() BLOCK past the timeout when a grandchild holds stdout?
// (classic os/exec Wait hang). sandbox.go leaves Stdout/Stderr nil.
func TestNoHangOnInheritedStdout(t *testing.T) {
	dir := t.TempDir()
	body := "#!/bin/sh\n(sleep 30) &\nexit 0\n"
	start := time.Now()
	run(t, dir, body, 2*time.Second)
	if d := time.Since(start); d > 5*time.Second {
		t.Logf("FINDING: cmd.Run blocked %v on a live grandchild", d)
	}
}
GOEOF

