package secreview

import (
	"os"
	"path/filepath"
	"testing"
)

// Q5: does os.RemoveAll follow a symlink the hook planted?
func TestRemoveAllSymlink(t *testing.T) {
	base := t.TempDir()
	victim := filepath.Join(base, "victim")
	if err := os.MkdirAll(victim, 0o755); err != nil { t.Fatal(err) }
	if err := os.WriteFile(filepath.Join(victim, "precious"), []byte("x"), 0o644); err != nil { t.Fatal(err) }
	sandbox := filepath.Join(base, "sandbox")
	if err := os.MkdirAll(filepath.Join(sandbox, "d"), 0o755); err != nil { t.Fatal(err) }
	// hook plants a symlink to somewhere outside the sandbox
	if err := os.Symlink(victim, filepath.Join(sandbox, "d", "escape")); err != nil { t.Fatal(err) }
	if err := os.RemoveAll(sandbox); err != nil { t.Fatalf("RemoveAll: %v", err) }
	if _, err := os.Stat(filepath.Join(victim, "precious")); err != nil {
		t.Errorf("FINDING: RemoveAll followed the symlink and deleted outside the sandbox: %v", err)
	} else {
		t.Log("OK: RemoveAll unlinked the symlink, target untouched")
	}
}

// Q5b: can the hook make the sandbox un-removable, leaking its contents?
func TestRemoveAllLeak(t *testing.T) {
	base := t.TempDir()
	sandbox := filepath.Join(base, "sandbox")
	inner := filepath.Join(sandbox, "locked")
	if err := os.MkdirAll(inner, 0o755); err != nil { t.Fatal(err) }
	if err := os.WriteFile(filepath.Join(inner, "residue"), []byte("hook output"), 0o644); err != nil { t.Fatal(err) }
	if err := os.Chmod(inner, 0o000); err != nil { t.Fatal(err) }
	err := os.RemoveAll(sandbox) // sandbox.go: `defer os.RemoveAll(dir)` — error discarded
	if err != nil {
		t.Logf("FINDING: RemoveAll failed (%v) and sandbox.go discards this error -> temp dir leaks", err)
	}
	if _, statErr := os.Stat(sandbox); statErr == nil {
		t.Logf("FINDING: sandbox %s still on disk after RemoveAll", sandbox)
	}
	_ = os.Chmod(inner, 0o755)
}
GOEOF
