package secreview

import (
	"os"
	"os/exec"
	"path/filepath"
	"strings"
	"testing"
)

func shQuote(s string) string { return "'" + strings.ReplaceAll(s, "'", `'\''`) + "'" }

// Q4: can any path escape shQuote inside the generated stub?
func TestShQuoteNoEscape(t *testing.T) {
	dir := t.TempDir()
	adversarial := []string{
		`plain`, `with space`, `it's`, `';touch /tmp/PWNED;'`, `'"'"'`,
		"a\nb", `$(touch /tmp/PWNED2)`, "`touch /tmp/PWNED3`", `${IFS}`,
		`\`, `''''`, `a'\''b`, `*`, `~`, `!`,
	}
	for _, name := range adversarial {
		logPath := filepath.Join(dir, "log")
		// exact stub construction from sandbox.go
		stub := "#!/bin/sh\nprintf '%s\\n' \"$*\" >> " + shQuote(logPath+"::"+name) + "\nexit 0\n"
		p := filepath.Join(dir, "stub")
		if err := os.WriteFile(p, []byte(stub), 0o755); err != nil { t.Fatal(err) }
		cmd := exec.Command(p, "audit", "seal")
		cmd.Env = []string{"PATH=/usr/bin:/bin"}
		out, err := cmd.CombinedOutput()
		if err != nil {
			t.Errorf("name=%q: stub failed to run: %v (%s)", name, err, out)
			continue
		}
		if len(out) != 0 {
			t.Errorf("name=%q: stub produced output (sign of injection): %q", name, out)
		}
		want := logPath + "::" + name
		data, err := os.ReadFile(want)
		if err != nil {
			t.Errorf("name=%q: expected literal file not written: %v", name, err)
			continue
		}
		if strings.TrimSpace(string(data)) != "audit seal" {
			t.Errorf("name=%q: bad log content %q", name, data)
		}
	}
	for _, p := range []string{"/tmp/PWNED", "/tmp/PWNED2", "/tmp/PWNED3"} {
		if _, err := os.Stat(p); err == nil {
			t.Errorf("FINDING: injection succeeded, %s created", p)
			_ = os.Remove(p)
		}
	}
}
GOEOF
