package doctor

import (
	"os"
	"os/exec"
	"path/filepath"
	"testing"
)

// A: does doctor execute hook content in a repo where ethos is NOT enabled?
func TestSecReviewExecutesOnDormantRepo(t *testing.T) {
	repo := t.TempDir()
	if out, err := exec.Command("git", "-C", repo, "init", "-q").CombinedOutput(); err != nil {
		t.Skipf("git unavailable: %v %s", err, out)
	}
	// NO .punt-labs/ethos/enabled marker: this repo is dormant.
	beacon := filepath.Join(repo, "BEACON-dormant")
	hook := filepath.Join(repo, ".git", "hooks", "pre-commit")
	if err := os.MkdirAll(filepath.Dir(hook), 0o755); err != nil {
		t.Fatal(err)
	}
	body := "#!/bin/sh\n: > " + beacon + "\nexit 0\n"
	if err := os.WriteFile(hook, []byte(body), 0o755); err != nil {
		t.Fatal(err)
	}
	res := CheckSealHook(repo)
	t.Logf("verdict: %s / %s", res.Status, res.Detail)
	if _, err := os.Stat(beacon); err == nil {
		t.Errorf("FINDING: foreign hook EXECUTED on a repo where ethos is not enabled")
	} else {
		t.Log("hook not executed on dormant repo")
	}
}

// B: sandbox containment when the caller's env carries GIT_DIR
// (doctor invoked from inside a git hook, `git rebase -x`, `git bisect run`,
// `git submodule foreach`) AND TMPDIR is inside a repo (the punt-labs
// standard: TMPDIR=<repo>/.tmp via .envrc).
func TestSecReviewSandboxEscapesViaGitDir(t *testing.T) {
	victim := t.TempDir()
	if out, err := exec.Command("git", "-C", victim, "init", "-q").CombinedOutput(); err != nil {
		t.Skipf("git unavailable: %v %s", err, out)
	}
	tmp := filepath.Join(victim, ".tmp")
	if err := os.MkdirAll(tmp, 0o755); err != nil {
		t.Fatal(err)
	}
	t.Setenv("TMPDIR", tmp)                              // punt-labs standard
	t.Setenv("GIT_DIR", filepath.Join(victim, ".git"))   // caller is under git

	// A foreign hook that operates on "the repo it is running in".
	body := "#!/bin/sh\n" +
		"top=$(git rev-parse --show-toplevel 2>/dev/null) || exit 0\n" +
		"printf 'escaped-to:%s\\n' \"$top\" > \"$top/BEACON-escape\"\n" +
		"ethos audit seal\n"

	observed, err := hookInvocationObserved([]byte(body), []string{"audit", "seal"}, false)
	t.Logf("hookInvocationObserved => %v, %v", observed, err)

	if _, statErr := os.Stat(filepath.Join(victim, "BEACON-escape")); statErr == nil {
		data, _ := os.ReadFile(filepath.Join(victim, "BEACON-escape"))
		t.Errorf("FINDING: sandbox escaped — hook wrote into the REAL repo work tree: %s", data)
	} else {
		t.Log("contained: no write into the real repo")
	}
	if err == nil && !observed {
		t.Logf("FINDING: correctly-installed hook reported INACTIVE (false FAIL)")
	}
}
