package doctor

import (
	"os/exec"
	"strings"
	"testing"

	"github.com/punt-labs/ethos/v4/internal/textscan"
)

// The discarded cmd.Run() error makes "could not execute" indistinguishable
// from "executed and did not call ethos". CRLF is the Unix instance of the
// same class the Windows path hits.
func TestSecReviewCRLFHookSilentFalseFail(t *testing.T) {
	if _, err := exec.LookPath("git"); err != nil {
		t.Skip("git unavailable")
	}
	unix := "#!/bin/sh\nethos audit seal\n"
	crlf := strings.ReplaceAll(unix, "\n", "\r\n")

	t.Logf("IsShellHook(LF)=%v  IsShellHook(CRLF)=%v",
		textscan.IsShellHook([]byte(unix)), textscan.IsShellHook([]byte(crlf)))

	okLF, errLF := hookInvocationObserved([]byte(unix), []string{"audit", "seal"}, false)
	t.Logf("LF   => observed=%v err=%v", okLF, errLF)

	okCRLF, errCRLF := hookInvocationObserved([]byte(crlf), []string{"audit", "seal"}, false)
	t.Logf("CRLF => observed=%v err=%v", okCRLF, errCRLF)

	if textscan.IsShellHook([]byte(crlf)) && !okCRLF && errCRLF == nil {
		t.Errorf("FINDING: CRLF hook classified as shell, failed to exec, reported inactive with NO error — silent false FAIL")
	}
}
GOEOF
